const topic = msg.topic || '';

// drop HA discovery/state noise, broker system topics, Tasmota's own
// discovery service messages, and anything under the literal
// 'tasmota' topic word. comment these out if you want literally
// everything.
if (/^homeassistant\//.test(topic)) return null;
if (/^\$SYS\//.test(topic)) return null;
if (/^discovery\//.test(topic)) return null;
if (/^tasmota\//.test(topic)) return null;

// drop anything matching one of the app's user-configured filter_regex
// patterns, tested against both the topic and the raw payload text.
const patterns = context.get('filterPatterns') || [];
if (patterns.length > 0) {
    const payloadStr = Buffer.isBuffer(msg.payload) ? msg.payload.toString('utf8') : String(msg.payload);
    for (const re of patterns) {
        if (re.test(topic) || re.test(payloadStr)) return null;
    }
}

return msg;

