// runs once when the node starts/redeploys: compile the app's
// filter_regex option (passed in as a JSON array via FILTER_REGEX_JSON)
// into real RegExp objects, so per-message handling above doesn't
// re-parse/re-compile them on every MQTT message.
const raw = env.get('FILTER_REGEX_JSON') || '[]';
let patterns = [];
try {
    patterns = JSON.parse(raw).map((p) => new RegExp(p));
} catch (e) {
    node.warn('FILTER_REGEX_JSON contains an invalid pattern, ignoring filter_regex: ' + e.message);
}
context.set('filterPatterns', patterns);

func:
// preserve payload verbatim as a UTF-8 string, whatever it was
let raw;
if (Buffer.isBuffer(msg.payload)) {
    raw = msg.payload.toString('utf8');
} else if (typeof msg.payload === 'string') {
    raw = msg.payload;
} else {
    raw = JSON.stringify(msg.payload);
}

let format = 'text';
try {
    JSON.parse(raw);
    format = 'json';
} catch (e) {
    format = 'text';
}

msg.rawPayload = raw;
msg.format = format;
return msg;

const topic = msg.topic || '';
const parts = topic.split('/').filter(p => p.length > 0);

// Tasmota's default FullTopic is <prefix>/<device>/<endpoint>, where
// prefix is one of cmnd/stat/tele - so the device name is the SECOND
// segment there. Everything else uses <device>/.../<endpoint>, so the
// device name is the FIRST segment.
const TASMOTA_PREFIXES = ['cmnd', 'stat', 'tele'];
const isTasmota = TASMOTA_PREFIXES.includes((parts[0] || '').toLowerCase());

const device = (isTasmota ? parts[1] : parts[0]) || 'unknown';
const type = parts[parts.length - 1] || 'unknown'; // last topic level

msg.labels = {
    source: 'mqtt',
    device: device,
    type: type,
    topic: topic,
    format: msg.format
};
return msg;

const ns = (BigInt(Date.now()) * 1000000n).toString();

msg.headers = { 'Content-Type': 'application/json' };
msg.payload = {
    streams: [{
        stream: msg.labels,
        values: [[ns, msg.rawPayload]]
    }]
};
return msg;

if (msg.statusCode >= 200 && msg.statusCode < 300) {
    return [msg, null];
}

msg.errorInfo = {
    statusCode: msg.statusCode,
    statusMessage: msg.statusMessage,
    topic: msg.labels ? msg.labels.topic : msg.topic
};
return [null, msg];

let stats = flow.get('mqttStats') || { total: 0, byDevice: {}, byType: {}, byFormat: {} };

stats.total++;
const d = msg.labels.device;
const t = msg.labels.type;
const f = msg.labels.format;
stats.byDevice[d] = (stats.byDevice[d] || 0) + 1;
stats.byType[t] = (stats.byType[t] || 0) + 1;
stats.byFormat[f] = (stats.byFormat[f] || 0) + 1;

flow.set('mqttStats', stats);
msg.payload = stats;
return msg;

const stats = flow.get('mqttStats') || { total: 0, byDevice: {}, byType: {}, byFormat: {} };
const ns = (BigInt(Date.now()) * 1000000n).toString();

msg.headers = { 'Content-Type': 'application/json' };
msg.payload = {
    streams: [{
        stream: { source: 'mqtt-logger', type: 'stats' },
        values: [[ns, JSON.stringify(stats)]]
    }]
};
return msg;

const ns = (BigInt(Date.now()) * 1000000n).toString();

const detail = {
    message: msg.error ? (msg.error.message || String(msg.error)) : JSON.stringify(msg.errorInfo || {}),
    topic: (msg.labels && msg.labels.topic) || msg.topic || 'unknown'
};

msg.headers = { 'Content-Type': 'application/json' };
msg.payload = {
    streams: [{
        stream: {
            source: 'mqtt-logger',
            type: 'error',
            device: (msg.labels && msg.labels.device) || 'mqtt-logger'
        },
        values: [[ns, JSON.stringify(detail)]]
    }]
};
return msg;
